    LaunchedEffect(running,scenario.name){while(running){delay(1700);frame=(frame+1)%scenario.frames.size}};val point=scenario.frames[frame];if(showWarning)WarningDialog(true,{showWarning=false},{running=false;showWarning=false})
    PageScaffold("Demo call",nav){Column(Modifier.fillMaxSize().verticalScroll(scrollState).padding(20.dp),verticalArrangement=Arrangement.spacedBy(13.dp)){DemoBadge();Text(scenario.name,style=MaterialTheme.typography.headlineSmall,fontWeight=FontWeight.Bold);Text(scenario.description,color=SignalMuted);DemoSummaryCard("Overall guidance",scenario.demoPresentation().overall,scenario.demoPresentation().detail,riskColor(scenario.demoPresentation().tone));Column(verticalArrangement=Arrangement.spacedBy(6.dp)){DemoScenario.scenarios.chunked(2).forEach { row -> Row(horizontalArrangement=Arrangement.spacedBy(6.dp),modifier=Modifier.fillMaxWidth()){row.forEach { option -> FilterChip(selected=option.name==scenario.name,onClick={vm.selectedScenario=option;frame=0},label={Text(option.name, maxLines=1, overflow=TextOverflow.Ellipsis)},modifier=Modifier.weight(1f)) } } }};Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){scenario.frames.indices.forEach{index->Box(Modifier.weight(1f).height(5.dp).clip(CircleShape).background(if(index<=frame)riskColor(point.risk.warningLevel) else SignalMuted.copy(.25f)))}};Waveform(frame,running);StatusRow("Signal",if(point.speaking)"Speech detected" else "Silence / listening");StatusRow("Audio quality",point.risk.audioQuality.label());TranscriptPreview(point.text,point.suspicious){nav.navigate(Route.Transcript)};RiskCards(point.risk){nav.navigate(Route.Result)};EvidencePanel(point.risk.evidence);if(point.risk.warningLevel!=WarningLevel.LOW)Button(onClick={showWarning=true},modifier=Modifier.fillMaxWidth().height(50.dp)){Text("Review warning guidance")};Row(horizontalArrangement=Arrangement.spacedBy(10.dp),modifier=Modifier.fillMaxWidth()){OutlinedButton(onClick={running=!running},modifier=Modifier.weight(1f).height(50.dp)){Text(if(running)"Pause demo" else "Continue Monitoring")};OutlinedButton(onClick={running=false},modifier=Modifier.weight(1f).height(50.dp)){Text("Stop Monitoring")}};OutlinedButton(onClick