@Composable private fun StatusRow(label:String,value:String)=Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(label,fontWeight=FontWeight.SemiBold);Text(value,color=SignalMuted,modifier=Modifier.widthIn(max=210.dp),textAlign=TextAlign.End)}
