@Composable private fun Detail(label:String,value:String)=Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.SpaceBetween){Text(label,color=SignalMuted);Text(value,fontWeight=FontWeight.SemiBold,textAlign=TextAlign.End)}
@Composable private fun Waveform(frame:Int,active:Boolean)=Canvas(Modifier.fillMaxWidth().height(102.dp).clip(RoundedCornerShape(16.dp)).background(MaterialTheme.colorScheme.surfaceVariant).semantics{contentDescription=if(active)"Animated simulated audio waveform" else "Inactive waveform placeholder"}){val center=size.height/2;val bars=28;repeat(bars){i->val pulse=if(active)((i*7+frame*11)%23)/23f else .12f;val h=10.dp.toPx()+pulse*size.height*.38f;val x=(i+.5f)*size.width/bars;drawLine(if(active)SignalBlue else SignalMuted,Offset(x,center-h),Offset(x,center+h),strokeWidth=4.dp.toPx(),cap=StrokeCap.Round)}}
@Composable private fun TranscriptPreview(text:String,suspicious:Boolean,onOpen:()->Unit)=Card(colors=CardDefaults.cardColors(containerColor=if(suspicious)AlertRed.copy(.17f) else MaterialTheme.colorScheme.surfaceVariant),modifier=Modifier.fillMaxWidth().clickable(onClick=onOpen)){Column(Modifier.padding(14.dp)){SectionTitle("Live transcript • simulated");Spacer(Modifier.height(6.dp));Text(text,maxLines=3,overflow=TextOverflow.Ellipsis,fontWeight=if(suspicious)FontWeight.SemiBold else FontWeight.Normal);if(suspicious)Text("Suspicious sentence highlighted",color=AlertRed,style=MaterialTheme.typography.labelSmall)}}
@Composable private fun EmptyRiskCards()=Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){listOf("Voice manipulation","Speaker mismatch","Scam risk").forEach{Card(Modifier.weight(1f),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surfaceVariant)){Text("$it\nNot available",modifier=Modifier.padding(10.dp),color=SignalMuted,style=MaterialTheme.typography.labelSmall)}}}
@Composable private fun RiskCards(risk:RiskResult,onOpen:()->Unit)=Row(horizontalArrangement=Arrangement.spacedBy(8.dp),modifier=Modifier.fillMaxWidth()){ScoreCard("Voice manipulation",risk.manipulation,onOpen);ScoreCard("Speaker mismatch",risk.speakerMismatch,onOpen);ScoreCard("Scam risk",risk.scamRisk,onOpen)}
@Composable private fun RowScope.ScoreCard(label:String,score:Int,onOpen:()->Unit){val level=levelOf(score);Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surfaceVariant),modifier=Modifier.weight(1f).clickable(onClick=onOpen)){Column(Modifier.padding(10.dp)){Text(label,color=SignalMuted,fontSize=11.sp,lineHeight=14.sp);Text("$score",fontSize=28.sp,fontWeight=FontWeight.Bold,color=riskColor(level));Text(level.title(),fontSize=10.sp,color=riskColor(level))}}}
@Composable private fun WarningHeader(level:WarningLevel,confidence:Int)=Card(colors=CardDefaults.cardColors(containerColor=riskColor(level).copy(.16f)),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text("${level.title()} warning level",color=riskColor(level),fontWeight=FontWeight.Bold,fontSize=19.sp);Text("Confidence: $confidence% • Demo result",color=Mist)}}
