@Composable private fun ToggleRow(title:String,detail:String,checked:Boolean,onChanged:(Boolean)->Unit)=Row(Modifier.fillMaxWidth().padding(vertical=6.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(title,fontWeight=FontWeight.SemiBold);Text(detail,color=SignalMuted,style=MaterialTheme.typography.bodySmall)};Switch(checked=checked,onCheckedChange=onChanged)}
@Composable private fun WarningDialog(demo:Boolean,onDismiss:()->Unit,onEndDemo:()->Unit)=AlertDialog(onDismissRequest=onDismiss,title={Text("Verify before you share")},text={Text("Suspicious voice or conversation patterns were detected. This is a warning, not proof. Avoid sharing OTPs, passwords, PINs or payment information. Verify the caller using an official number.")},confirmButton={Button(onClick=onDismiss){Text("Continue Monitoring")}},dismissButton={Column(horizontalAlignment=Alignment.End){OutlinedButton(onClick=onDismiss){Text("Stop Monitoring")};OutlinedButton(onClick=onDismiss){Text("Verify Caller")};OutlinedButton(onClick=onDismiss){Text("Open Phone Controls")};if(demo)Button(onClick=onEndDemo){Text("End Demo Call")}}})

private data class FileInfo(val name:String,val size:String,val type:String)
private fun Context.fileInfo(uri:Uri):FileInfo{var name="Selected audio";var size="Size unavailable";contentResolver.query(uri,arrayOf(OpenableColumns.DISPLAY_NAME,OpenableColumns.SIZE),null,null,null)?.use{if(it.moveToFirst()){name=it.getString(0)?:name;val bytes=it.getLong(1);if(bytes>=0)size="${bytes/1024} KB"}};return FileInfo(name,size,contentResolver.getType(uri)?:"Audio file")}
@Composable private fun FileCard(file:FileInfo)=Card(colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.surfaceVariant),modifier=Modifier.fillMaxWidth()){Column(Modifier.padding(16.dp)){Text(file.name,fontWeight=FontWeight.SemiBold);Text("${file.type} • ${file.size}",color=SignalMuted,style=MaterialTheme.typography.bodySmall)}}
private fun AudioQuality.label()=when(this){AudioQuality.GOOD->"Good";AudioQuality.NOISY->"Noisy";AudioQuality.INSUFFICIENT->"Insufficient audio";AudioQuality.UNKNOWN->"Unknown"}
private fun WarningLevel.title()=when(this){WarningLevel.LOW->"Low indication";WarningLevel.UNCERTAIN->"Uncertain — verify";WarningLevel.HIGH->"High indication"}
private fun levelOf(score:Int)=when(score){in 0..34->WarningLevel.LOW;in 35..69->WarningLevel.UNCERTAIN;else->WarningLevel.HIGH}
private fun riskColor(level:WarningLevel)=when(level){WarningLevel.LOW->SafeGreen;WarningLevel.UNCERTAIN->Amber;WarningLevel.HIGH->AlertRed}

@Composable private fun DemoSummaryCard(title:String,heading:String,detail:String,color:Color)=Card(colors=CardDefaults.cardColors(containerColor=color.copy(.15f)),modifier=Modifier.fillMaxWidth().semantics{contentDescription="$title. $heading. $detail. Simulated demo."}){Column(Modifier.padding(16.dp),verticalArrangement=Arrangement.spacedBy(6.dp)){Text(title,color=SignalMuted,style=MaterialTheme.typography.labelLarge);Text(heading,color=color,style=MaterialTheme.typography.titleLarge,fontWeight=FontWeight.ExtraBold);Text(detail)}}

private data class DemoPresentation(val overall:String,val detail:String,val tone:WarningLevel,val voice:String,val voiceDetail:String,val voiceColor:Color,val fraud:String,val fraudDetail:String,val fraudColor:Color)
private fun DemoScenario.demoPresentation()=when(name){
    "Trusted human voice"->DemoPresentation("NO STRONG WARNING SIGNS","Both simulated checks completed without a strong warning. This is not a safety guarantee.",WarningLevel.LOW,"LIKELY HUMAN VOICE","No strong simulated AI-generated speech indicators were detected.",SafeGreen,"NO STRONG SCAM LANGUAGE DETECTED","No strong simulated scam-language pattern was found. This is not a guarantee of safety.",SafeGreen)
    "Noisy or insufficient audio"->DemoPresentation("REVIEW THIS RECORDING","Poor simulated audio quality makes the result inconclusive.",WarningLevel.UNCERTAIN,"INCONCLUSIVE","The simulated recording quality was insufficient for a reliable result.",Amber,"FRAUD CHECK INCONCLUSIVE","The simulated transcript evidence was insufficient.",Amber)
    "Suspected AI-generated voice"->DemoPresentation("HIGH CAUTION RECOMMENDED","Possible simulated AI-generated/manipulated voice patterns and suspicious language were detected.",WarningLevel.HIGH,"LIKELY AI-GENERATED OR MANIPULATED","The simulated recording contains acoustic patterns associated with manipulated speech.",AlertRed,"SUSPICIOUS LANGUAGE DETECTED","Simulated transcript context should be independently verified.",Amber)
    "Suspected voice clone"->DemoPresentation("ANALYSIS INCOMPLETE","This legacy scenario illustrates an unavailable check; speaker verification is not included.",WarningLevel.UNCERTAIN,"AI VOICE CHECK NOT PERFORMED","The simulated acoustic check is unavailable in this example. No voice-clone conclusion is produced.",SignalMuted,"SUSPICIOUS LANGUAGE DETECTED","The simulated request for a security code should be verified.",Amber)
    "Suspicious scam conversation"->DemoPresentation("HIGH CAUTION RECOMMENDED","High-risk simulated scam language was detected independently of the voice result.",WarningLevel.HIGH,"LIKELY HUMAN VOICE","No strong simulated acoustic manipulation indicator was detected; this does not make the request safe.",SafeGreen,"HIGH SCAM RISK","Simulated confirmed context includes an OTP request and urgency.",AlertRed)
    else->DemoPresentation("HIGH CAUTION RECOMMENDED","Both simulated acoustic and scam-language warnings are present.",WarningLevel.HIGH,"LIKELY AI-GENERATED OR MANIPULATED","Simulated acoustic patterns may be associated with manipulated speech.",AlertRed,"HIGH SCAM RISK","Simulated confirmed context includes credential requests and pressure.",AlertRed)
}

private data class DemoPoint(val speaking:Boolean,val text:String,val suspicious:Boolean,val risk:RiskResult)
private data class DemoScenario(val name:String,val description:String,val frames:List<DemoPoint>,val transcript:List<TranscriptSegment>){companion object{
    private fun r(m:Int,s:Int,c:Int,confidence:Int,quality:AudioQuality=AudioQuality.GOOD,evidence:List<EvidenceReason> = emptyList())=RiskResult(m,s,c,confidence,levelOf(maxOf(m,s,c)),quality,38,evidence)
    private fun e(title:String,detail:String)=EvidenceReason(title,detail)
    private fun transcript(vararg rows:Triple<String,String,Boolean>)=rows.mapIndexed{i,row->TranscriptSegment("00:${(i*8+3).toString().padStart(2,'0')}",row.second,if(i%2==0)"English" else "Hinglish",confirmed=i<2,suspicious=row.third)}
    val scenarios=listOf(
      DemoScenario("Trusted human voice","A calm baseline scenario with no simulated warning evidence.",listOf(DemoPoint(true,"Hi, I called to confirm our meeting tomorrow.",false,r(12,8,10,82)),DemoPoint(false,"",false,r(8,6,8,85)),DemoPoint(true,"Thank you, see you then.",false,r(10,7,9,86))),transcript(Triple("","Hi, I called to confirm our meeting tomorrow.",false),Triple("","Haan, calendar mein add kar diya.",false),Triple("","Thank you, see you then.",false))),
      DemoScenario("Noisy or insufficient audio","The timeline demonstrates an unusable input, not a risk conclusion.",listOf(DemoPoint(true,"[background traffic and clipped speech]",false,r(0,0,0,20,AudioQuality.NOISY,listOf(e("Audio quality","Background noise prevents a reliable assessment.")))),DemoPoint(false,"[silence]",false,r(0,0,0,12,AudioQuality.INSUFFICIENT,listOf(e("Insufficient speech","Collect more clear speech before assessing.")))),DemoPoint(true,"Could you repeat that?",false,r(0,0,0,25,AudioQuality.NOISY))),transcript(Triple("","[unclear audio]",false),Triple("","Could you repeat that?",false))),
      DemoScenario("Suspected AI-generated voice","Preset synthetic-speech indicators rise, then soften when clean speech changes.",listOf(DemoPoint(true,"Your account needs immediate verification.",true,r(43,12,40,71,evidence=listOf(e("Voice pattern","Simulated unusually regular prosody.")))),DemoPoint(true,"Please open the secure link now.",true,r(78,18,62,84,evidence=listOf(e("Voice pattern","Simulated spectral consistency."),e("Urgency language","Pressure to act immediately.")))),DemoPoint(false,"",false,r(58,14,44,78,evidence=listOf(e("Voice pattern","Simulation remains uncertain."))))),transcript(Triple("","Your account needs immediate verification.",true),Triple("","Please open the secure link now.",true),Triple("","Main abhi busy hoon.",false))),
      DemoScenario("Suspected voice clone","Preset voice mismatch evidence is shown as a caution, never proof of identity.",listOf(DemoPoint(true,"It's me. I need a quick favour.",false,r(32,46,35,68,evidence=listOf(e("Speaker match","Simulated mismatch against an enrolled voice.")))),DemoPoint(true,"Can you send the code I just received?",true,r(61,82,72,88,evidence=listOf(e("Speaker match","Simulated voice-print mismatch."),e("Sensitive request","One-time code requested.")))),DemoPoint(false,"",false,r(48,66,54,78,evidence=listOf(e("Speaker match","Verify identity through another channel."))))),transcript(Triple("","It's me. I need a quick favour.",false),Triple("","Can you send the code I just received?",true))),
      DemoScenario("Suspicious scam conversation","The warning comes from simulated conversation context rather than a voice claim.",listOf(DemoPoint(true,"Your KYC will expire today, sir.",true,r(14,10,56,76,evidence=listOf(e("Scam language","Simulated deadline pressure.")))),DemoPoint(true,"Share the OTP so I can secure the account.",true,r(18,14,91,91,evidence=listOf(e("Scam language","OTP requested."),e("Urgency language","Action requested without verification.")))),DemoPoint(false,"",false,r(10,8,67,82,evidence=listOf(e("Scam language","Use an official number to verify."))))),transcript(Triple("","Your KYC will expire today, sir.",true),Triple("","Share the OTP so I can secure the account.",true))),
      DemoScenario("High combined risk","A deterministic combined-risk showcase with scores that can rise and fall.",listOf(DemoPoint(true,"This is bank security. Act now.",true,r(55,62,72,83,evidence=listOf(e("Voice pattern","Simulated manipulation indicator."),e("Scam language","Urgent authority claim.")))),DemoPoint(true,"Give me the PIN and OTP before the account locks.",true,r(91,88,96,94,evidence=listOf(e("Voice pattern","Simulated synthetic-speech indicator."),e("Speaker match","Simulated mismatch."),e("Sensitive request","PIN and OTP requested.")))),DemoPoint(false,"",false,r(63,69,71,87,evidence=listOf(e("Combined signal","Warning persists; verify caller independently."))))),transcript(Triple("","This is bank security. Act now.",true),Triple("","Give me the PIN and OTP before the account locks.",true),Triple("","I will call the official number.",false)))
    )
}}
